<script setup>
import IeltsNavigation from '../components/IeltsNavigation.vue'
import {ref,reactive,onMounted} from 'vue'
import ielts from '../api/ielts.js'
const names={listening:'听力',reading:'阅读',writing:'写作',speaking:'口语'}
const profile=reactive({targetBand:6.5,skillTargets:{listening:6.5,reading:6.5,writing:6,speaking:6},examDate:'',dailyMinutes:30})
const access=ref(null),speechKey=ref(''),message=ref(''),error=ref(''),busy=ref(false),materials=ref([])
const material=reactive({title:'',topic:'',body:''})
const usageNames={'writing-feedback':'写作反馈','speaking-feedback':'口语反馈',transcription:'语音转写',invitation:'邀请额度'}
const usageStates={settled:'已完成',reserved:'处理中',released:'未扣额度',grant:'已发放'}
async function load(){try{const [p,a,m]=await Promise.all([ielts.profile(),ielts.access(),ielts.materials()]);Object.assign(profile,p);profile.examDate ||= '';access.value=a;materials.value=m.materials}catch(e){error.value=e.message}}
async function saveGoal(){busy.value=true;message.value='';error.value='';try{await ielts.saveProfile(profile);message.value='学习目标已保存'}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveAccess(){busy.value=true;error.value='';message.value='';try{await ielts.saveAccess({...access.value.preferences,...(speechKey.value?{speechKey:speechKey.value}:{})});speechKey.value='';message.value='服务选择已保存。失败时不会自动切换到另一付费来源。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveMaterial(){busy.value=true;error.value='';try{await ielts.saveMaterial(material);Object.assign(material,{title:'',topic:'',body:''});materials.value=(await ielts.materials()).materials;message.value='素材已保存'}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="ielts-page"><IeltsNavigation/><header class="ielts-heading"><div><h1>我的备考设置</h1><p>目标、服务选择和可反复使用的表达素材。</p></div><router-link class="btn btn-ghost" to="/settings">完整偏好设置</router-link></header><p v-if="error" class="ielts-error" role="alert">{{error}}</p><p class="ielts-status" role="status">{{message}}</p>
<section class="ielts-section"><h2>Academic 学习目标</h2><form class="ielts-form" @submit.prevent="saveGoal"><label>目标总分<input v-model.number="profile.targetBand" type="number" min="1" max="9" step="0.5" required></label><label>考试日期（可留空）<input v-model="profile.examDate" type="date"></label><label v-for="(name,key) in names" :key="key">{{name}}目标<input v-model.number="profile.skillTargets[key]" type="number" min="1" max="9" step="0.5" required></label><label>每天学习分钟数<input v-model.number="profile.dailyMinutes" type="number" min="5" max="240" required></label><div class="ielts-wide"><button class="btn btn-primary" :disabled="busy">保存学习目标</button></div></form></section>
<section v-if="access" class="ielts-section"><h2>AI 和语音服务</h2><p>平台可用额度：<strong>{{access.wallet.available}}</strong>，处理中预占 {{access.wallet.reserved}}。试运营期间通过邀请发放，暂未开放在线购买。</p><p class="muted">基础训练、客观题判分和已保存记录免费。平台 AI 成功结果消耗额度；个人 Key 由你与服务商结算。</p><form class="ielts-form" @submit.prevent="saveAccess"><label>文字模型<select v-model="access.preferences.textMode"><option value="platform">平台额度</option><option value="byok">个人文字 Key</option></select></label><label>语音识别<select v-model="access.preferences.speechMode"><option value="platform">平台额度</option><option value="byok">个人语音 Key</option></select></label><div class="ielts-wide"><router-link to="/settings">配置个人文字 Key 和模型</router-link></div><template v-if="access.preferences.speechMode==='byok'"><label>语音服务 HTTPS 地址<input v-model="access.preferences.speechBaseUrl" type="url" placeholder="https://服务商地址/v1"></label><label>语音模型<input v-model="access.preferences.speechModel" maxlength="100"></label><label class="ielts-wide">个人语音 Key {{access.preferences.speechConfigured?'（已保存，留空沿用）':''}}<input v-model="speechKey" type="password" autocomplete="new-password" placeholder="密钥加密保存，不会回传"></label></template><div class="ielts-wide"><button class="btn btn-primary" :disabled="busy">保存服务选择</button></div></form><details><summary>最近 30 天调用记录</summary><p v-for="(u,i) in access.wallet.usage" :key="i">{{usageNames[u.kind] || '学习服务'}} · {{u.source==='server'?'平台':'个人 Key'}} · {{usageStates[u.state] || '已记录'}} · {{u.calls}} 次</p></details></section>
<section class="ielts-section"><h2>我的表达素材</h2><p class="muted">记录自己的故事、观点和搭配，用于不同话题的独立表达。</p><form class="ielts-form" @submit.prevent="saveMaterial"><label>素材标题<input v-model="material.title" maxlength="190" required></label><label>关联话题<input v-model="material.topic" maxlength="100" placeholder="例如：学习、环境、旅行"></label><label class="ielts-wide">素材内容<textarea v-model="material.body" maxlength="20000" required></textarea></label><div class="ielts-wide"><button class="btn btn-primary" :disabled="busy">保存素材</button></div></form><div class="ielts-archive"><details v-for="m in materials" :key="m.id"><summary>{{m.title}} · {{m.topic}}</summary><pre>{{m.body}}</pre></details></div></section>
</div></template>
